    {tab==='output'&&<><p>完整前缀的实际下一token分布（前12项展示）</p><table className="v6-table"><thead><tr><th>token</th><th>概率</th></tr></thead><tbody>{d.output_top.map(x=><tr key={x.token_id}><td>{x.text} / {x.token_id}</td><td>{num(x.probability)}</td></tr>)}</tbody></table><p className="v8-note">此表是模型实测输出。上方局部计算关联不是一个已经能独立替代原模型的图谱预测器。</p></>}
  </section></div></>}
  </div>;
}

import {useState} from 'react';
const pct=v=>Number.isFinite(v)?`${(v*100).toFixed(2)}%`:'未提供';
export default function EntityArbitrationReport({doc:input}){
  const d=input.scope_accuracy?{...input,heldout_entities:input.n_heldout_entities,
    native:{files:input.native_audit.native_files_verified,bytes:input.native_audit.native_bytes,generation_steps:input.examples.reduce((n,e)=>n+(Math.max(0,(e.generation.trace_ids?.length||0)-1)),0)},
    scope_stats:Object.entries(input.scope_accuracy).map(([scope,accuracy])=>({scope,accuracy,n:192})),source_free_prior_accuracy:input.source_free_reference_accuracy,H1:input.scope_effect,
    head_tests:Object.entries(input.head_ablation).map(([condition,drop])=>({condition,accuracy:1-drop.mean,drop})),
    counterexamples_count:input.counterexamples.length,cells:input.cell_statistics.map(c=>({...c,accuracy:c.reference_accuracy,correct:Math.round(c.reference_accuracy*c.n),frame:'合并'})),
    trace_preview:input.examples.map(e=>({...e,n_tokens:e.length})),generations:input.examples.map(e=>e.generation),references:input.artifact_refs}:input;
  const [tab,setTab]=useState('result'),[page,setPage]=useState(0);
  const link=t=>`/workbench?lens=spatial&view=live&trace=${t}`;
  return <section aria-label="实体属性仲裁真实研究报告"><p><strong>{d.behavior_gate?'范围行为门通过':'范围行为门未通过'} · {d.H2_supported?'Head组效应支持':'Head组效应未支持'}</strong></p><p className="v8-note">{d.run_id} · 本地Qwen3-4B / CUDA BF16 · 原权重快照保持一致。负结果与原场完整保留，不将执行完成计为机制发现。</p>
    <div className="v8-library-stats"><span><b>{d.n_inputs}</b>等长成对长文本</span><span><b>{d.heldout_entities}</b>留出实体</span><span><b>{d.native.files.toLocaleString()}</b>前缀原场文件，逐个校验哈希</span></div>
    <div className="v6-toolbar">{[['result','结果与判据'],['trace','三模块真实路径'],['errors',`反例与失败（${d.counterexamples_count}）`],['sources','预注册与来源']].map(([k,t])=><button className={'fw-tbtn'+(tab===k?' primary':'')} key={k} onClick={()=>setTab(k)}>{t}</button>)}</div>
    {tab==='result'&&<><p>{d.scope_stats.map(s=>`${s.scope}：${pct(s.accuracy)}（${s.n}条）`).join('；')}。源外常识探针：{pct(d.source_free_prior_accuracy)}。</p><p>同实体的文档偏好差：{pct(d.H1.mean)}，实体家族bootstrap区间 [{d.H1.ci95.map(pct).join(', ')}]。预注册要求差≥50个百分点且区间下界&gt;20个百分点，并通过两范围各≥80%的行为门。</p><table className="v6-table"><thead><tr><th>干预</th><th>留出正确率</th><th>下降（实体区间）</th></tr></thead><tbody>{d.head_tests.map(t=><tr key={t.condition}><td>{t.condition==='selected_heads'?'发现集选出的8个后段Head':'同块匹配的8个随机Head'}</td><td>{pct(t.accuracy)}</td><td>{pct(t.drop.mean)} [{t.drop.ci95.map(pct).join(', ')}]</td></tr>)}</tbody></table><p className="v8-note">H2要求下降≥20个百分点、区间下界&gt;0且超过随机对照。未支持不等于所有Head无效。</p>{!d.capability||d.capability.status==='not_tested'||!d.capability.loss_interval?<p className="v8-note">能力保持：未触发新操作的2200题检验，不能声称已通过。此处是二值组消融，没有把它包装成剂量曲线。</p>:<p className="v8-note">额外探索性能力监控：{d.capability.n}题，净损失 {(100*d.capability.net_loss).toFixed(2)} 个百分点，95%区间 [{d.capability.loss_interval.map(v=>(100*v).toFixed(2)).join(', ')}] 个百分点，允许损失2个百分点；{d.capability.status==='noninferior'?'通过非劣效门':'尚未通过'}。该监控在仲裁结果之后登记、在自身输出之前冻结，使用重复题池；不能挽救未支持的H1/H2。此处是二值组消融，没有把它包装成剂量曲线。</p>}{d.reference_quality&&<p className="v8-note">两名独立AI对48条参考颜色进行事后盲审：双方均认为典型且较唯一 {d.reference_quality.both_typical}/48，意见不同 {d.reference_quality.disagreements}/48；不是人工金标，不改变冻结标签与主判。</p>}<details><summary>全部句式、长度与范围条件格</summary><table className="v6-table"><tbody>{d.cells.map((c,i)=><tr key={i}><td>{c.split} / {c.scope}</td><td>F{c.frame} / {c.length}</td><td>{c.correct}/{c.n} · {pct(c.accuracy)}</td></tr>)}</tbody></table></details></>}
    {tab==='trace'&&<><p>选择真实输入，在3D索引空间联动查询Embedding、全部Head、完整MLP阵列和原参数贡献。</p>{d.trace_preview.map(t=><p key={t.trace_id}><a href={t.url||link(t.trace_id)}>{t.entity} · {t.scope} · {t.n_tokens} tokens → 打开3D计算路径</a></p>)}<p className="v8-note">37层HiddenState、36块全部HeadZ与9728个MLP单元保存于声明的三个读出位置；这8条额外保存全输入位置HiddenState及Q/K/V。共 {(d.native.bytes/2**30).toFixed(2)} GiB，实际生成步原场 {d.native.generation_steps}。</p><details><summary>8条真实自由生成</summary>{d.generations.map(g=><p key={g.sample_id}>{g.sample_id}：{g.text}（{g.hit_limit?'触及长度上限':'未触及长度上限'}）</p>)}</details></>}
    {tab==='errors'&&<><p className="v8-note">所有原模型错误和干预错误均可回查，没有事后删除失败实体。</p>{d.counterexamples.slice(page*20,(page+1)*20).map((e,i)=><details key={i}><summary>{e.entity||e.family_id||'预注册检验'} · {e.scope||e.condition||e.reason}</summary><pre className="v8-sample-text">{JSON.stringify(e,null,2)}</pre>{e.trace_id&&<a href={link(e.trace_id)}>回查此反例的真实内部响应</a>}</details>)}<div className="v6-toolbar"><button className="fw-tbtn" disabled={!page} onClick={()=>setPage(p=>p-1)}>上一页</button><span>{page+1} / {Math.max(1,Math.ceil(d.counterexamples.length/20))}</span><button className="fw-tbtn" disabled={(page+1)*20>=d.counterexamples.length} onClick={()=>setPage(p=>p+1)}>下一页</button></div></>}
    {tab==='sources'&&<><details open><summary>适用边界与硬伤</summary>{d.limitations.map(x=><p key={x} className="v8-note">{x}</p>)}</details><details><summary>事前冻结的预注册</summary><pre className="v8-sample-text">{JSON.stringify(d.preregistration,null,2)}</pre></details><details><summary>原场审计与数据引用</summary><pre className="v8-sample-text">{JSON.stringify({model_snapshot:d.model_snapshot,references:d.references,native:d.native,provenance:d.provenance},null,2)}</pre></details></>}
  </section>;
}

import { useState } from 'react';
import { useApi } from '../app/rdc_fusion/api.js';
import { Empty } from '../app/rdc_fusion/ui.jsx';
import { orderedStages } from './researchFragmentUtil.js';
import ResearchInterventionReport from './ResearchInterventionReport.jsx';
import DatasetAtlasPlan from './DatasetAtlasPlan.jsx';
import ResearchCatalog from './ResearchCatalog.jsx';

function Workpackage({w,onGo,childRuns=[]}){
  const [expanded,setExpanded]=useState(new URLSearchParams(window.location.search).get('run')===w.body.run_id);
  const report=w.body.stages?.registration_validated?.report_sha256;
  const datasetPlan=w.body.stages?.dataset_atlas_plan?.plan_sha256;
  return <details open={expanded} onToggle={e=>setExpanded(e.currentTarget.open)}>
    <summary>{w.body.title||w.body.run_id}</summary>
    <p className="v8-note">{w.body.run_id} · 更新于 {new Date(w.body.updated_at*1000).toLocaleString()}</p>
    <div className="v8-workpackage-stages">{orderedStages(w.body.stages).map(([k,s])=><span key={k}>
      <b>{({freeze:'冻结材料',registry:'数据与图谱登记',native_audit:'生成全场审计',ai_review:'外部AI盲评',pilot:'行为试跑',collection:'原场采集',intervention:'预注册组干预',interface:'统一采集接口',discovery:'候选发现',registration_discovery:'登记观察',validation:'留出验证',capability:'能力保持',registration_validated:'登记修订',client_acceptance:'客户端回查',dataset_atlas_plan:'数据与图谱方案'})[k]||k}</b>
      {s.state==='not_supported'&&s.baseline_gate===false?'△ 测量门未通过':({done:'✓ 已完成',not_tested:'未测试',partial:'部分已完成',running:'执行中',ready:'已冻结，待执行',proposed:'方案待实施',not_supported:'△ 未支持',behavior_failed:'△ 行为门失败',noninferior:'✓ 非劣效通过',inferior:'△ 超过允许损失',inconclusive:'△ 尚未证实'})[s.state]||s.state}
    </span>)}</div>
    {expanded&&report&&<ResearchInterventionReport sha={report}/>}
    {expanded&&datasetPlan&&<DatasetAtlasPlan sha={datasetPlan} implementation={w.body.stages.dataset_atlas_plan.state==='partial'}/>}
    {expanded&&childRuns.length>0&&<details><summary>前置校准与试跑（{childRuns.length}）</summary>{childRuns.map(c=><Workpackage key={c.sha} w={c} onGo={onGo}/>)}</details>}
    <button className="fw-tbtn" onClick={()=>onGo('route',null,null,{rtab:'rules'})}>查看拼图与证据</button>
  </details>;
}

export default function ResearchExecution({ plan=false,onGo }){
  const tasks=useApi(plan?null:'/api/tasks',{online:true});
  const packages=useApi('/api/research-library/workpackages');
  const allPackages=packages.data?.workpackages||[];
  const roots=allPackages.filter(w=>!allPackages.some(p=>p!==w&&p.body.run_id===w.body.parent_run_id&&!p.body.parent_run_id));
  return <div className="v8-route"><section className="v8-card"><h2>{plan?'整体图谱研究路线':'执行与审计'}</h2><p className="v8-note">统一材料与行为门 → 全层长文本采集 → 原生单元/Head候选 → 参数路径与干预 → 未见组合预测 → 跨模型复现。每轮产物持续进入证据库，失败和未解释区域也保留。</p></section>
    <div className="v8-direction-cards">{[['材料与测量','冻结实体、属性、角色、语境及语法文法，512/1024/2048 token面板按模型试跑校准。'],['计算图谱','保留完整坐标与MLP阵列，分别记录观察关联、留出复现、参数来源、干预和反例。'],['留出与复算','依次Qwen3-4B、GLM4-9B、Qwen3-14B，CUDA bf16。独立内容家族留出，不跨快照/精度合并。']].map(([t,p])=><section className="v8-card" key={t}><h3>{t}</h3><p className="v8-note">{p}</p></section>)}</div>
    <section className="v8-card"><div className="v6-toolbar"><button className="fw-tbtn" onClick={()=>onGo('catalog')}>任务与数据</button><button className="fw-tbtn" onClick={()=>onGo('route',null,null,{rtab:'rules'})}>持续研究库与证据</button><button className="fw-tbtn" onClick={()=>onGo('config',null,null,{csec:'account'})}>贡献算力 / 节点托管</button></div></section>
    <ResearchCatalog/>
    <section className="v8-card"><div className="v6-toolbar"><h3>实际研究工作包</h3><button className="fw-tbtn" onClick={packages.reload}>刷新工作包</button></div><p className="v8-note">阶段记录来自研究生产者，执行结束不表示假设成立；离线客户端更新数据包后查看最新状态。</p>
      {packages.error?<Empty>{packages.error}</Empty>:!packages.data?<Empty>读取工作包…</Empty>:!allPackages.length?<Empty>尚无已登记工作包。</Empty>:roots.map(w=><Workpackage key={w.sha} w={w} onGo={onGo} childRuns={allPackages.filter(c=>c.body.parent_run_id===w.body.run_id&&c!==w)}/>)}
    </section>
    {!plan&&<section className="v8-card"><div className="v6-toolbar"><h3>真实调度队列</h3><button className="fw-tbtn" onClick={tasks.reload}>刷新队列</button></div>{tasks.error?<Empty>{tasks.error}</Empty>:!tasks.data?<Empty>读取…</Empty>:<><div className="v8-library-stats">{[['queued','排队'],['claimed','执行中'],['done','已完成'],['failed','失败']].map(([k,t])=><span key={k}><b>{tasks.data.stats?.[k]||0}</b>{t}</span>)}</div><p className="v8-note">状态时间 {new Date(tasks.data.server_time*1000).toLocaleString()}；完成表示执行结束，研究证据另行审计。</p><details><summary>当前任务与最近记录</summary><table className="v6-table"><thead><tr><th>任务 / 模板</th><th>节点</th><th>状态</th><th>结果哈希</th></tr></thead><tbody>{[...(tasks.data.queued||[]).map(r=>({...r,status:'queued'})),...(tasks.data.active||[]).map(r=>({...r,status:'claimed'})),...(tasks.data.recent||[])].map(r=><tr key={r.task_id}><td>{r.task_id}<small>{r.tm_id}</small></td><td>{r.node_name||'—'}</td><td>{r.status}</td><td>{r.result_sha?.slice(0,12)||'—'}</td></tr>)}</tbody></table></details></>}</section>}
  </div>;
}

